CREATE OR REPLACE FUNCTION public.save_project_with_assignments(p_project_id uuid DEFAULT NULL, p_data jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_project public.projects%ROWTYPE; v_role text := public.cf_current_role(); v_columns text; v_changes jsonb; v_key text; v_assignment_role text; BEGIN IF auth.uid() IS NULL OR v_role IS NULL OR v_role NOT IN ('super_admin', 'pm') THEN RAISE EXCEPTION 'Insufficient permissions to save project'; END IF; v_changes := p_data - 'site_managers' - 'workers' - 'suppliers' - 'admins'; IF p_project_id IS NULL THEN INSERT INTO public.projects (name, location, start_date, end_date, pm_id, client_id, status, total_budget, address, latitude, longitude) SELECT (v_changes->>'name')::text, (v_changes->>'location')::text, (v_changes->>'start_date')::date, (v_changes->>'end_date')::date, (v_changes->>'pm_id')::uuid, (v_changes->>'client_id')::uuid, COALESCE((v_changes->>'status')::text, 'planning'), COALESCE((v_changes->>'total_budget')::numeric, 0), (v_changes->>'address')::text, (v_changes->>'latitude')::numeric, (v_changes->>'longitude')::numeric RETURNING * INTO v_project; ELSE UPDATE public.projects SET name = COALESCE((v_changes->>'name')::text, name), location = COALESCE((v_changes->>'location')::text, location), start_date = COALESCE((v_changes->>'start_date')::date, start_date), end_date = COALESCE((v_changes->>'end_date')::date, end_date), pm_id = COALESCE((v_changes->>'pm_id')::uuid, pm_id), client_id = COALESCE((v_changes->>'client_id')::uuid, client_id), status = COALESCE((v_changes->>'status')::text, status), total_budget = COALESCE((v_changes->>'total_budget')::numeric, total_budget), address = COALESCE((v_changes->>'address')::text, address), latitude = COALESCE((v_changes->>'latitude')::numeric, latitude), longitude = COALESCE((v_changes->>'longitude')::numeric, longitude) WHERE id = p_project_id RETURNING * INTO v_project; IF NOT FOUND THEN RAISE EXCEPTION 'Project not found'; END IF; END IF; FOR v_key, v_assignment_role IN VALUES ('site_managers', 'site_manager'), ('workers', 'worker'), ('suppliers', 'supplier'), ('admins', 'super_admin') LOOP IF p_data ? v_key THEN DELETE FROM public.project_role_assignments WHERE project_id = v_project.id AND assigned_role = v_assignment_role; INSERT INTO public.project_role_assignments (project_id, user_id, assigned_role, assigned_by) SELECT v_project.id, (u.id)::uuid, v_assignment_role, auth.uid() FROM jsonb_array_elements_text(p_data->v_key) AS u(id); END IF; END LOOP; RETURN to_jsonb(v_project); END; $$;
